    """
    def execute(self):
        from ranger.ext.vcs import VcsError
        import tempfile
        L = self.fm.thistab.get_selection()
        if len(L) == 0: return
        filelist = [f.path for f in L]
        vcs = L[0].vcs
        diff = vcs.get_raw_diff(filelist=filelist)
        if len(diff.strip()) > 0:
            tmp = tempfile.NamedTemporaryFile()
            tmp.write(diff.encode('utf-8'))
