        public static bool BadaoCast(this Spell spell, Obj_AI_Base target)
        {
            var prediction = spell.GetBadaoPrediction(target);
            if (!spell.IsSkillshot)
                return false;
            if (prediction.Hitchance < spell.MinHitChance)
                return false;
